"""Ordered, generator-based jq evaluation."""
from __future__ import annotations
import base64, json, math, re, urllib.parse
from collections.abc import Iterator
from .data_model import JsonValue, is_truthy
from .diagnostics import RuntimeJqError
from .parser import Filter

def _walk(v):
    yield v
    if isinstance(v,dict):
        for x in v.values(): yield from _walk(x)
    elif isinstance(v,list):
        for x in v: yield from _walk(x)

def _num(x):
    if isinstance(x,bool) or not isinstance(x,(int,float)): raise RuntimeJqError('number required')
    return x

def _call(name,args,inp,env):
    if name=='map' and args:
        yield [z for x in inp for z in ev(args[0],x,env)]
        return
    if name=='map_values' and args:
        yield [next(ev(args[0],x,env),None) for x in inp] if isinstance(inp,list) else next(ev(args[0],inp,env))
        return
    vals=[list(ev(a,inp,env)) for a in args]
    def one(i=0): return vals[i][0] if vals[i] else None
    if name=='range':
        a=_num(one()); b=_num(vals[1][0]) if len(vals)>1 else a; step=_num(vals[2][0]) if len(vals)>2 else 1
        if len(vals)==1: a,b=0,a
        if step==0: raise RuntimeJqError('range step cannot be zero')
        x=a
        while (step>0 and x<b) or (step<0 and x>b): yield x; x+=step
    elif name in ('length','utf8bytelength'):
        yield len(one()) if not isinstance(one(),(int,float)) else abs(one())
    elif name=='type': yield 'null' if one() is None else ('boolean' if isinstance(one(),bool) else 'number' if isinstance(one(),(int,float)) else 'string' if isinstance(one(),str) else 'array' if isinstance(one(),list) else 'object')
    elif name=='keys': yield list(range(len(one()))) if isinstance(one(),list) else sorted(one().keys())
    elif name=='values':
        if one() is not None: yield one()
    elif name in ('tonumber','tostring','tojson','fromjson'):
        x=one()
        if name=='tonumber': yield float(x) if '.' in str(x) else int(x)
        elif name=='tostring': yield x if isinstance(x,str) else json.dumps(x,separators=(',',':'))
        elif name=='tojson': yield json.dumps(x,ensure_ascii=False,separators=(',',':'))
        else: yield json.loads(x)
    elif name in ('add','any','all','flatten','sort','unique','reverse','min','max'):
        x=one()
        if name=='add': yield sum(x) if x and all(isinstance(a,(int,float)) for a in x) else ''.join(x)
        elif name=='any': yield any(is_truthy(a) for a in x)
        elif name=='all': yield all(is_truthy(a) for a in x)
        elif name=='flatten':
            def flat(a):
                for q in a: yield from flat(q) if isinstance(q,list) else (q,)
            yield list(flat(x))
        elif name in ('sort','unique'): yield sorted(set(x)) if name=='unique' else sorted(x)
        elif name=='reverse': yield x[::-1]
        else: yield (min if name=='min' else max)(x)
    elif name=='contains': yield _contains(one(),vals[1][0])
    elif name=='startswith': yield one().startswith(vals[1][0])
    elif name=='endswith': yield one().endswith(vals[1][0])
    elif name=='floor': yield math.floor(_num(one()))
    elif name=='ceil': yield math.ceil(_num(one()))
    elif name=='abs': yield abs(_num(one()))
    elif name=='sqrt': yield math.sqrt(_num(inp))
    elif name=='not': yield not is_truthy(inp)
    elif name in ('arrays','objects','iterables','scalars','booleans','nulls','strings','numbers'):
        ok={'arrays':isinstance(inp,list),'objects':isinstance(inp,dict),'iterables':isinstance(inp,(list,dict)),'scalars':not isinstance(inp,(list,dict)),'booleans':isinstance(inp,bool),'nulls':inp is None,'strings':isinstance(inp,str),'numbers':isinstance(inp,(int,float)) and not isinstance(inp,bool)}[name]
        if ok: yield inp
    elif name=='join': yield (vals[0][0] if vals else '').join('' if x is None else str(x).lower() if isinstance(x,bool) else str(x) for x in inp)
    elif name=='split': yield one().split(vals[1][0])
    elif name in ('ltrimstr','rtrimstr','trimstr'):
        q=one(); x=inp
        if name=='ltrimstr': yield x[len(q):] if x.startswith(q) else x
        elif name=='rtrimstr': yield x[:-len(q)] if q and x.endswith(q) else x
        else: yield x[len(q):] if x.startswith(q) else x[:-len(q)] if q and x.endswith(q) else x
    elif name=='range': return
    elif name=='error': raise RuntimeJqError(str(one()) if args else 'error')
    elif name in ('in','inside'): yield False
    else: raise RuntimeJqError('unknown function '+name)

def _contains(a,b):
    if isinstance(a,str) and isinstance(b,str): return b in a
    if isinstance(a,list) and isinstance(b,list): return all(x in a for x in b)
    if isinstance(a,dict) and isinstance(b,dict): return all(k in a and _contains(a[k],v) for k,v in b.items())
    return a==b

def ev(f:Filter, inp:JsonValue, env:dict[str,JsonValue]|None=None)->Iterator[JsonValue]:
    env={} if env is None else env; k=f.kind
    if k=='identity': yield inp
    elif k=='literal': yield f.value
    elif k=='empty': return
    elif k=='error': raise RuntimeJqError('error')
    elif k=='comma':
        for c in f.children: yield from ev(c,inp,env)
    elif k=='field':
        for x in ev(f.children[0],inp,env):
            if isinstance(x,dict): yield x.get(f.value)
            else: raise RuntimeJqError('cannot index')
    elif k=='iterate':
        for x in ev(f.value[0],inp,env):
            if isinstance(x,(list,dict)): yield from (x if isinstance(x,list) else x.values())
            else: raise RuntimeJqError('cannot iterate')
    elif k in ('index','slice'):
        base,a,b=f.value
        for x in ev(base,inp,env):
            for ix in ev(a, x, env):
                if k=='index': yield x[ix] if isinstance(x,(list,dict,str)) else None
                else:
                    lo=ix; hi=None if b is None else next(ev(b,x,env),None); yield x[lo:hi]
    elif k=='array': yield [z for c in f.children for z in ev(c,inp,env)]
    elif k=='object':
        out={}
        for key,c in f.value: out[key]=next(ev(c,inp,env),None)
        yield out
    elif k=='unary':
        for x in ev(f.children[0],inp,env): yield -_num(x)
    elif k=='call': yield from _call(str(f.value),f.children,inp,env)
    elif k=='binary':
        op=f.value; l,r=f.children
        if op=='|':
            for x in ev(l,inp,env): yield from ev(r,x,env)
        elif op==',': yield from ev(l,inp,env); yield from ev(r,inp,env)
        else:
            for a in ev(l,inp,env):
                for b in ev(r,inp,env): yield _binary(op,a,b)
    elif k=='recurse': yield from _walk(inp)
    else: raise RuntimeJqError('unsupported filter')

def _binary(op,a,b):
    if op=='//': return a if is_truthy(a) else b
    if op in ('==','!=','<','>','<=','>='): return {'==':a==b,'!=':a!=b,'<':a<b,'>':a>b,'<=':a<=b,'>=':a>=b}[op]
    if op=='+':
        if isinstance(a,dict) and isinstance(b,dict): return {**a,**b}
        if isinstance(a,list) and isinstance(b,list): return a+b
        return a+b
    if op=='-': return a-b if isinstance(a,(int,float)) else [x for x in a if x not in b]
    if op=='*': return a*b
    if op=='/': return a/b if not isinstance(a,str) else a.split(b)
    if op=='%': return a%b
    raise RuntimeJqError('unsupported operator')

evaluate=ev

"""Small lexical boundary for the foundational filter syntax."""

from __future__ import annotations

from dataclasses import dataclass
import json

from .diagnostics import CompileError


@dataclass(frozen=True)
class Token:
    kind: str
    value: object
    position: int


def tokenize(program: str) -> list[Token]:
    tokens: list[Token] = []
    index = 0
    while index < len(program):
        char = program[index]
        if char.isspace():
            index += 1
        elif char == ".":
            tokens.append(Token("DOT", char, index))
            index += 1
        elif char == ",":
            tokens.append(Token("COMMA", char, index))
            index += 1
        elif char == '"':
            try:
                value, end = json.JSONDecoder().raw_decode(program[index:])
            except json.JSONDecodeError as exc:
                raise CompileError(f"invalid string at position {index}") from exc
            if not isinstance(value, str):
                raise CompileError(f"invalid string at position {index}")
            tokens.append(Token("LITERAL", value, index))
            index += end
        elif char.isdigit() or char == "-":
            try:
                value, end = json.JSONDecoder().raw_decode(program[index:])
            except json.JSONDecodeError as exc:
                raise CompileError(f"invalid number at position {index}") from exc
            if not isinstance(value, (int, float)) or isinstance(value, bool):
                raise CompileError(f"invalid number at position {index}")
            tokens.append(Token("LITERAL", value, index))
            index += end
        elif char.isalpha() or char == "_":
            end = index + 1
            while end < len(program) and (program[end].isalnum() or program[end] == "_"):
                end += 1
            tokens.append(Token("IDENT", program[index:end], index))
            index = end
        else:
            raise CompileError(f"unexpected character at position {index}")
    tokens.append(Token("EOF", None, len(program)))
    return tokens
"""A compact parser for the jq expression language used by the CLI."""
from __future__ import annotations
from dataclasses import dataclass
import json
import re
from .diagnostics import CompileError

@dataclass(frozen=True)
class Filter:
    kind: str
    value: object = None
    children: tuple["Filter", ...] = ()

class Parser:
    def __init__(self, source: str) -> None:
        self.s = source; self.i = 0; self.t: list[tuple[str,object,int]] = []
        self.lex(); self.p = 0
    def lex(self) -> None:
        s=self.s; i=0
        while i<len(s):
            if s[i].isspace(): i+=1; continue
            if s[i]=='#':
                while i<len(s) and s[i]!='\n': i+=1
                continue
            if s[i]=='"':
                try: v,n=json.JSONDecoder().raw_decode(s[i:])
                except json.JSONDecodeError as e: raise CompileError("invalid string") from e
                self.t.append(('str',v,i)); i+=n; continue
            m=re.match(r'(?:-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?)',s[i:])
            if m:
                raw=m.group(); self.t.append(('num',json.loads(raw),i)); i+=len(raw); continue
            m=re.match(r'[A-Za-z_][A-Za-z_0-9]*',s[i:])
            if m:
                raw=m.group(); self.t.append(('id',raw,i)); i+=len(raw); continue
            found=False
            for op in ('//=', '...','..','?//','//','|=','+=','-=','*=','/=','==','!=','<=','>=','as','=>'):
                if s.startswith(op,i): self.t.append((op,op,i)); i+=len(op); found=True; break
            if found: continue
            if s[i] in '.[],{}():;|,+-*/%=<>?!@$': self.t.append((s[i],s[i],i)); i+=1; continue
            raise CompileError(f"unexpected character at position {i}")
        self.t.append(('EOF',None,len(s)))
    def peek(self,*ks:str)->bool: return self.t[self.p][0] in ks
    def pop(self,k:str|None=None):
        x=self.t[self.p]
        if k and x[0]!=k: raise CompileError(f"expected {k} at position {x[2]}")
        self.p+=1; return x
    def parse(self)->Filter:
        if self.peek('EOF'): raise CompileError('empty filter')
        x=self.expr(0)
        if not self.peek('EOF'): raise CompileError(f"unexpected token at position {self.t[self.p][2]}")
        return x
    def expr(self,minp:int)->Filter:
        left=self.primary()
        prec={',':1,'|':2,'?//':3,'//':4,'==':5,'!=':5,'<':5,'>':5,'<=':5,'>=':5,'+':6,'-':6,'*':7,'/':7,'%':7,'=':0,'|=':0,'+=':0,'-=':0}
        while self.t[self.p][0] in prec and prec[self.t[self.p][0]]>=minp:
            op=self.pop()[0]; p=prec[op]; right=self.expr(p+1)
            left=Filter('binary',op,(left,right))
        return left
    def primary(self)->Filter:
        k,v,pos=self.pop()
        if k=='EOF': raise CompileError('expected filter')
        if k=='.':
            x=Filter('identity')
            while True:
                if self.peek('id'):
                    name=self.pop()[1]; x=Filter('field',name,(x,))
                elif self.peek('.') and self.p+1 < len(self.t) and self.t[self.p+1][0]=='id':
                    self.pop(); name=self.pop()[1]; x=Filter('field',name,(x,))
                elif self.peek('['):
                    self.pop('[')
                    if self.peek(']'): self.pop(); x=Filter('iterate',(x,))
                    else:
                        a=None if self.peek(':') else self.expr(0); b=None
                        if self.peek(':'):
                            self.pop(); b=None if self.peek(']') else self.expr(0)
                            x=Filter('slice',(x,a,b))
                        else: x=Filter('index',(x,a,None))
                        self.pop(']')
                else: break
            return x
        if k in ('num','str'): return Filter('literal',v)
        if k=='id':
            if v in ('true','false','null'): return Filter('literal',{'true':True,'false':False,'null':None}[v])
            if v in ('empty','error'): return Filter(v)
            if self.peek('('):
                self.pop(); args=[]
                if not self.peek(')'):
                    while True:
                        args.append(self.expr(0))
                        if not self.peek(';',','): break
                        self.pop()
                self.pop(')'); return Filter('call',v,tuple(args))
            if v in {'length','keys','values','type','add','any','all','flatten','sort','unique','reverse','min','max','floor','ceil','abs','not','arrays','objects','iterables','scalars','booleans','nulls','strings','numbers','tojson','fromjson','tostring','tonumber','sqrt','empty'}:
                return Filter('call',v,())
            raise CompileError(f"unknown filter at position {pos}")
        if k=='[':
            items=[]
            if not self.peek(']'):
                while True:
                    items.append(self.expr(0))
                    if not self.peek(','): break
                    self.pop()
            self.pop(']'); return Filter('array',children=tuple(items))
        if k=='{':
            items=[]
            if not self.peek('}'):
                while True:
                    key=self.pop()
                    if key[0] not in ('id','str'): raise CompileError('invalid object key')
                    self.pop(':'); items.append((str(key[1]),self.expr(0)))
                    if not self.peek(','): break
                    self.pop()
            self.pop('}'); return Filter('object',items)
        if k=='(':
            x=self.expr(0); self.pop(')'); return x
        if k=='-': return Filter('unary','-',(self.primary(),))
        if k=='.' and self.peek('..'): return Filter('recurse')
        raise CompileError(f"expected filter at position {pos}")

def parse(program:str)->Filter: return Parser(program).parse()

